#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int lb(const vector<int>& v, int x) {
  return lower_bound(begin(v), end(v), x) - begin(v);
}
int sz(const vector<int>& v) { return v.size(); }

int main() {
  int N, Q;
  string S;
  cin >> N >> Q >> S;

  vector<int> idx1, idx2, idxs;
  for (int i = 0; i < N; i++) {
    (S[i] == '1' ? idx1 : S[i] == '2' ? idx2 : idxs).push_back(i);
  }
  while (Q--) {
    int l, r;
    cin >> l >> r;
    --l;

    // 1, 2 の長さが len である 11/22 文字列が存在するか？
    auto f = [&](int len) -> bool {
      if (len == 0) {
        // / を発見
        int j = lb(idxs, l);
        if (j >= sz(idxs)) return false;
        return idxs[j] < r;
      }
      // 1 を発見
      int i = lb(idx1, l);
      if (i + len - 1 >= sz(idx1)) return false;
      // / を発見
      int j = lb(idxs, idx1[i + len - 1]);
      if (j >= sz(idxs)) return false;
      // 2 を発見
      int k = lb(idx2, idxs[j]);
      if (k + len - 1 >= sz(idx2)) return false;
      return idx2[k + len - 1] < r;
    };

    int ok = -1, ng = N + 1;
    while (ok + 1 < ng) {
      int m = (ok + ng) / 2;
      (f(m) ? ok : ng) = m;
    }
    cout << (ok == -1 ? 0 : ok * 2 + 1) << "\n";
  }
}

#include<bits/stdc++.h>

using namespace std;

int lb(int x,vector<int> &a){
  int l=0,r=((int)a.size())-1;
  while(l<=r){
    int te=(l+r)/2;
    if(a[te]<x){l=te+1;}
    else{r=te-1;}
  }
  return l;
}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n,q;
  cin >> n >> q;
  string s;
  cin >> s;
  vector<int> c1(n+1,0);
  vector<int> c2(n+1,0);
  vector<int> sl;
  for(int i=0;i<n;i++){
    c1[i+1]=c1[i];
    c2[i+1]=c2[i];
    if(s[i]=='1'){
      c1[i+1]++;
    }
    else if(s[i]=='2'){
      c2[i+1]++;
    }
    else{
      sl.push_back(i+1);
    }
  }
  // for(auto &nx : c1){
  //   cout << nx << " ";
  // }cout << "\n";
  // for(auto &nx : c2){
  //   cout << nx << " ";
  // }cout << "\n";
  // for(auto &nx : sl){
  //   cout << nx << " ";
  // }cout << "\n";

  while(q>0){
    q--;
    int l,r;
    cin >> l >> r;
    int lef=lb(l,sl);
    int rig=lb(r+1,sl);
    if(lef==rig){
      cout << "0\n";
      continue;
    }
    rig--;

    int res=0;
    while(lef<=rig){
      int te=(lef+rig)/2;
      int pt=sl[te];

      int l1=(c1[pt]-c1[l-1]);
      int r2=(c2[r]-c2[pt]);

      res=max(res,2*min(l1,r2)+1);

      if(l1>r2){rig=te-1;}
      else{lef=te+1;}
    }
    cout << res << "\n";
  }
  return 0;
}
